/* @socom-skeleton stub GetRemoteAiState__11CRemoteCtrlFv */
u8 CRemoteCtrl::GetRemoteAiState()
{
	/* 0x2ce860: the low byte of the AI net state (vtable GetAiNetState) of a seal in a vehicle
	 * slot, else 0 */
	if (m_entity->m_vehicle_index == 0)
		return 0;
	u32 state = GetAiNetState();
	return (u8)(state & 0xff);
}

/* @socom-skeleton stub GetRemoteAiFollowMaster__11CRemoteCtrlFv */
CZSealBody *CRemoteCtrl::GetRemoteAiFollowMaster()
{
	/* 0x2ce790: in AI state 9 (following) the seal whose id is bits 8..23 of the net state */
	u8 ai = 0;
	if (m_entity->m_vehicle_index != 0)
		ai = (u8)(GetAiNetState() & 0xff);
	if (ai != 9)
		return NULL;
	u32 state = GetAiNetState();
	CEntity *master = CEntity::m_list.GetEntityById((state >> 8) & 0xffff);
	if (master != NULL && master->m_type == 2)
		return (CZSealBody *)master;
	return NULL;
}

/* @socom-skeleton stub OnCommand__11CRemoteCtrlFP10CZSealBody10FT_COMMANDPvb */
void CRemoteCtrl::OnCommand(CZSealBody *commander, FT_COMMAND command, void *point, bool)
{
	/* 0x2ce740: HOLDPOS (5) and FOLLOW (4) go to the remote seal's owner over the network */
	u8 cmd = (u8)command;
	if (cmd == 5 || cmd == 4)
		NetSendAiOrders(commander->m_id, m_entity->m_id, cmd, point);
}

/* @socom-skeleton stub AllowCommand__11CRemoteCtrlFP10CZSealBody10FT_COMMANDPv */
bool CRemoteCtrl::AllowCommand(CZSealBody *commander, FT_COMMAND command, void *)
{
	/* 0x2ce6e0: only HOLDPOS (5) and FOLLOW (4), as CSealCtrl decides them */
	u8 cmd = (u8)command;
	if (cmd == 5)
		return AllowCommandHOLDPOS(commander) != 0;
	if (cmd == 4)
		return AllowCommandFOLLOW(commander) != 0;
	return false;
}

/* @socom-skeleton stub Tick__11CRemoteCtrlFf */
bool CRemoteCtrl::Tick(float)
{
	/* 0x2ce6c0: a remote seal has no goal of its own */
	ClearGoal((GOAL_TYPE)0);
	return true;
}

/* @socom-skeleton stub PreTick__11CRemoteCtrlFf */
bool CRemoteCtrl::PreTick(float dT)
{
	/* @socom-skeleton stub sm$2347 */
	static float sm;
	/* @socom-skeleton stub last_time$2348 */
	static int last_time;
	/* 0x2ce310 (another machine's seal, each frame): once per network clock tick the smoothing
	 * factor sm = exp(-dT x the net game's m_pos_smooth). The node takes the received state's
	 * opacity and is on unless fully transparent. More than sqrt(1000) from the received
	 * position the seal jumps there (position, orientation, altitude); otherwise it moves
	 * toward it by sm (the received height taken as it is). The orientation turns toward the
	 * received one by min(2 sm, 1) (SlerpFaster). The aim: the received fire elevation e, the
	 * fire direction the node's forward axis scaled by sqrt(1 - e^2) with e as its height, the
	 * body-space aim (0, e, -sqrt(1 - e^2)). While rounds are left to replay one is fired from
	 * the fire point along that direction with the seal's velocity. v0 = 1. (init$2349 is the
	 * function-local static guard of last_time's first set.) */
	CZSealBody *seal = static_cast<CZSealBody *>(m_entity);
	f32 goal_y = m_remote_goal_pos.y;
	f32 rate = theMission.m_pNetGame->m_pos_smooth;
	static bool init = false; /* init$2349 */

	if (!init)
	{
		last_time = 0;
		init = true;
	}

	if (last_time != theNetwork.zNetGetTime())
	{
		last_time = theNetwork.zNetGetTime();
		sm = expf(-dT * rate);
	}

	SealAiNetState state;
	u32 word = m_ai_net_state;
	memcpy(&state, &word, 4);
	zdb::CNode *node = seal->GetNode();

	if (node != NULL)
	{
		node->SetActive(state.m_transparency != 15);
		node->m_Opacity = 1.0f - (f32)state.m_transparency / 15.0f;
	}

	CPnt3D d;
	m_remote_goal_pos.Sub(seal->GetPosW(), &d);

	if (!(d.x * d.x + d.y * d.y + d.z * d.z <= 1000.0f))
	{
		seal->GetNode()->SetPosition(m_remote_goal_pos.x, m_remote_goal_pos.y, m_remote_goal_pos.z);
		seal->m_quat.vec = m_remote_goal_quat.vec;
		seal->m_quat.w = m_remote_goal_quat.w;
		seal->ResetAltitude(m_remote_goal_pos.y);
	}
	else
	{
		CPnt3D to;
		seal->GetPosW()->Interp(&m_remote_goal_pos, sm, &to);
		to.y = goal_y;
		seal->GetNode()->SetPosition(to.x, to.y, to.z);
	}

	f32 t = 2.0f * sm;

	if (!(t <= 1.0f))
		t = 1.0f;
	else if (t < 0.0f)
		t = 0.0f;

	CQuat q;
	seal->m_quat.SlerpFaster(&m_remote_goal_quat, t, &q);
	seal->m_quat.vec = q.vec;
	seal->m_quat.w = q.w;
	f32 e = seal->m_RemoteFireElevation;
	f32 c = sqrtf(1.0f - e * e);
	const f32 (*m)[4] = seal->m_node->m_matrix.m_matrix;
	CPnt3D fire;
	fire.x = -m[2][0] * c;
	fire.y = e;
	fire.z = -m[2][2] * c;
	CPnt3D aim;
	aim.x = 0.0f;
	aim.y = e;
	aim.z = -c;
	seal->AimWeapon();
	seal->SetAimDirR(&aim, false);

	if (seal->m_RemoteRoundCount != 0)
	{
		seal->m_RemoteRoundCount--;
		CPnt3D fp;

		if (seal->GetFP(fp))
			seal->m_kit.FireCur(&fp, &fire, &static_cast<CZSealBody *>(m_entity)->m_velW);
	}

	return true;
}

/* @socom-skeleton stub PostMortemPreTick__11CRemoteCtrlFf */
void CRemoteCtrl::PostMortemPreTick(float)
{
	/* 0x2ce220 (returns 1 in the ELF): a dead remote seal (its id gone) fades out over 2 s from
	 * its time of death and its node is switched off once nearly transparent */
	CZSealBody *seal = (CZSealBody *)m_entity;
	if (seal->m_id != (u32)CEntity::invalidId)
		return;
	zdb::CNode *node = seal->GetNode();
	if (!node->m_active)
		return;
	m_fade_time = 2.0f;
	m_fade_min = 0.00100000005f /* 0x3a83126f */;
	f32 t = theMission.m_timer - seal->m_time_of_death;
	if (!(t <= m_fade_time)) /* _saturate<f>(&t, 0, m_fade_time) 0x1a8dd0: the max test first, NaN form */
		t = m_fade_time;
	else if (t < 0.0f)
		t = 0.0f;
	node->m_Opacity = 1.0f - t / m_fade_time;
	if (node->m_Opacity <= m_fade_min) {
		node->m_Opacity = 0.0f;
		node->SetActive(false);
	}
}

